import { AppCore } from './AppCore';
import { RendererCore } from './ThreeCore';
import { CLICK_TYPE } from './Utils/const';
import { View } from './View';

export class AppHypercube3d {
	static async init(id: string, ui: boolean = false) {
		const app = new AppHypercube3d(id, ui);
		await app.init();
		return app;
	}

	public threeCore!: RendererCore;
	public appCore!: AppCore;
	public view: View | undefined = undefined;
	public id: string;
	public navigationScene: boolean;
	public isPerformanceMode: boolean;

	public debuggerMode: boolean = true;

	constructor(id: string = 'main', ui: boolean = true) {
		const params = new URLSearchParams(window.location.search);
		const sc1 = params.get('sc');
		this.navigationScene = sc1 === '1';

		const sc2 = params.get('performance');
		this.isPerformanceMode = sc2 === 'true';
		this.id = id;

		if (ui) this.debuggerMode = ui;
	}
	public async init() {
		await this.initRenderer();
		if (this.debuggerMode) await this.initView();
		await this.initApp();

		this.bindEvent();
		this.bindRenderer();
	}
	private async initRenderer() {
		this.threeCore = new RendererCore(this.id, this.isPerformanceMode);
		await this.threeCore.init();
	}
	private async initView() {
		this.view = new View(this);
		await this.view.init();
	}
	private async initApp() {
		this.appCore = new AppCore(this, this.isPerformanceMode, this.navigationScene);
		await this.appCore.init();
	}

	public bindEvent() {
		this.threeCore.onMouseEventListener = (e: MouseEvent, type: CLICK_TYPE) => this.appCore.onMouseEventListener(e, type);
	}
	public bindRenderer() {
		this.threeCore.update = () => this.appCore.update();
	}
	public destroy() {
		this.threeCore?.destroy();
		this.view?.destroy();
		this.appCore?.destroy();
	}
}
