export class NVector3 {
	static eps: number = 0.0000001;
	static origin: NVector3 = new NVector3(0, 0, 0);

	x: number = 0.0;
	y: number = 0.0;
	z: number = 0.0;
	w: number = 0.0;
	long: number = 0.0;
	lat: number = 0.0;
	ele: number = 0.0;
	proX: number = 0.0;
	proY: number = 0.0;
	proZ: number = 0.0;
	alt: number = 0.0;
	d: boolean = true;
	isModified: boolean = false;

	// tslint:disable-next-line:no-any
	parent: any;

	static DeepCopy(v: NVector3): NVector3 {
		const out = new NVector3(v.x, v.y, v.z);
		out.long = v.long;
		out.lat = v.lat;
		out.proX = v.proX;
		out.proY = v.proY;
		out.proZ = v.proZ;
		return out;
	}
	static Dot(a: NVector3, b: NVector3) {
		return a.x * b.x + a.y * b.y + a.z * b.z;
	}
	static ScalarRev_V_S_OUT(v: NVector3, s: number, out: NVector3) {
		out.x = s * v.x;
		out.y = s * v.y;
		out.z = s * v.z;
		return out;
	}
	static Sub(v0: NVector3, v1: NVector3): NVector3 {
		return new NVector3(v1.x - v0.x, v1.y - v0.y, v1.z - v0.z);
	}
	static Clone(v: NVector3): NVector3 {
		return NVector3.DeepCopy(v);
	}
	static zAxis(): NVector3 {
		return new NVector3(0, 0, 1);
	}
	static zero(): NVector3 {
		return new NVector3(0, 0, 0);
	}
	static Origin(): NVector3 {
		return new NVector3(0, 0, 0);
	}
	static Plus(v1: NVector3, v2: NVector3): NVector3 {
		return new NVector3(v1.x + v2.x, v1.y + v2.y, v1.z + v2.z);
	}
	static Scale(v: NVector3, s: number): NVector3 {
		return new NVector3(v.x * s, v.y * s, v.z * s);
	}
	static MidVec(v1: NVector3, v2: NVector3): NVector3 {
		return new NVector3((v1.x + v2.x) * 0.5, (v1.y + v2.y) * 0.5, (v1.z + v2.z) * 0.5);
	}
	static CompareTwoVectors(v0: NVector3, v1: NVector3): boolean {
		if (v0.x !== v1.x || v0.y !== v1.y || v0.z !== v1.z) {
			return false;
		} else {
			return true;
		}
	}
	static Length(v: NVector3): number {
		return Math.sqrt(v.x * v.x + v.y * v.y + v.z * v.z);
	}
	static Normalize(v: NVector3): NVector3 {
		let len: number = Math.sqrt(v.x * v.x + v.y * v.y + v.z * v.z);
		return new NVector3(v.x / len, v.y / len, v.z / len);
	}
	static GetIndexByShortDistance(v: NVector3, vs: NVector3[]): number[] {
		let index = -1;
		let dis = Number.MAX_VALUE;
		for (let i = 0; i < vs.length; ++i) {
			let distance = NVector3.Distance(v, vs[i]);
			if (distance < dis) {
				dis = distance;
				index = i;
			}
		}
		return [index, dis];
	}
	static Distance(v0: NVector3, v1: NVector3): number {
		return Math.sqrt((v0.x - v1.x) * (v0.x - v1.x) + (v0.y - v1.y) * (v0.y - v1.y) + (v0.z - v1.z) * (v0.z - v1.z));
	}
	static Distance2(v1: NVector3, v2: NVector3): number {
		let d: number = (v1.x - v2.x) * (v1.x - v2.x) + (v1.y - v2.y) * (v1.y - v2.y) + (v1.z - v2.z) * (v1.z - v2.z);
		return d;
	}
	static DotProduct(v1: NVector3, v2: NVector3): number {
		return v1.x * v2.x + v1.y * v2.y + v1.z * v2.z;
	}
	static CrossProduct(v1: NVector3, v2: NVector3): NVector3 {
		return new NVector3(v1.y * v2.z - v1.z * v2.y, v1.z * v2.x - v1.x * v2.z, v1.x * v2.y - v1.y * v2.x);
	}
	static DivideByNum(v0: NVector3, v1: NVector3, n: number = 5): NVector3[] {
		let vs: NVector3[] = [];
		let xOff = (v1.x - v0.x) / n;
		let yOff = (v1.y - v0.y) / n;
		let zOff = (v1.z - v0.z) / n;
		for (let j = 0; j < n; ++j) {
			let x = v0.x + xOff * j;
			let y = v0.y + yOff * j;
			let z = v0.z + zOff * j;
			vs.push(new NVector3(x, y, z));
		}
		return vs;
	}
	static GetAngleBetween(v0: NVector3, v1: NVector3) {
		return Math.atan2(v1.x - v0.x, v1.y - v0.y);
	}
	// .................................................
	static GetCosAngleByTwoVectors(v0: NVector3, v1: NVector3): number {
		return NVector3.DotProduct(NVector3.Normalize(v0), NVector3.Normalize(v1));
	}
	static GetAngleByTwoVectorsRadian(v0: NVector3, v1: NVector3): number {
		return Math.acos(NVector3.GetCosAngleByTwoVectors(v0, v1));
	}
	static GetAngleByTwoVectors(v0: NVector3, v1: NVector3): number {
		return (NVector3.GetAngleByTwoVectorsRadian(v0, v1) * 180.0) / Math.PI;
	}
	static RotateVec(v: NVector3, angle: number): NVector3 {
		let cos = Math.cos(angle * (3.14159265358979 / 180.0));
		let sin = Math.sin(angle * (3.14159265358979 / 180.0));
		let x = v.x * cos - v.y * sin;
		let y = v.x * sin + v.y * cos;
		return new NVector3(x, y, v.z);
	}
	constructor(x: number, y: number, z: number = 0) {
		this.x = x;
		this.y = y;
		this.z = z;
	}
	Set(x: number, y: number, z: number): NVector3 {
		this.x = x;
		this.y = y;
		this.z = z;
		return new NVector3(this.x, this.y, this.z);
	}
	Scale(v: number): NVector3 {
		this.x *= v;
		this.y *= v;
		this.z *= v;
		return new NVector3(this.x, this.y, this.z);
	}
	Mult(v: number): NVector3 {
		this.x *= v;
		this.y *= v;
		this.z *= v;
		return new NVector3(this.x, this.y, this.z);
	}
	Div(v: number): NVector3 {
		this.x /= v;
		this.y /= v;
		this.z /= v;
		return new NVector3(this.x, this.y, this.z);
	}
	Add(v: NVector3): NVector3 {
		this.x += v.x;
		this.y += v.y;
		this.z += v.z;
		return new NVector3(this.x, this.y, this.z);
	}
	Sub(v: NVector3): NVector3 {
		this.x -= v.x;
		this.y -= v.y;
		this.z -= v.z;
		return new NVector3(this.x, this.y, this.z);
	}
	Negate() {
		this.x *= -1;
		this.y *= -1;
		this.z *= -1;
		return new NVector3(this.x, this.y, this.z);
	}
	Equals(v: NVector3) {
		return this.x === v.x && this.y === v.y && this.z === v.z;
	}
	Clone(): NVector3 {
		return new NVector3(this.x, this.y, this.z);
	}
	Length(): number {
		return Math.sqrt(this.x * this.x + this.y * this.y + this.z * this.z);
	}
	Unitize(): NVector3 {
		return this.Normalize();
	}
	Normalize(): NVector3 {
		let len: number = Math.sqrt(this.x * this.x + this.y * this.y + this.z * this.z);
		this.x = this.x / len;
		this.y = this.y / len;
		this.z = this.z / len;
		return new NVector3(this.x, this.y, this.z);
	}
	Distance(v: NVector3): number {
		return NVector3.Distance(new NVector3(this.x, this.y, this.z), v);
	}
	Distance2(v: NVector3): number {
		return NVector3.Distance2(new NVector3(this.x, this.y, this.z), v);
	}
	DotProduct(v: NVector3): number {
		return NVector3.DotProduct(new NVector3(this.x, this.y, this.z), v);
	}
	CrossProduct(v: NVector3): NVector3 {
		return NVector3.CrossProduct(new NVector3(this.x, this.y, this.z), v);
	}

	ToString(): string {
		let t: string = 'x: ' + this.x.toFixed(3).toString() + ' , y: ' + this.y.toFixed(3).toString() + ', z: ' + this.z.toFixed(3).toString();
		return t;
	}
}

export class NSolarRobust {
	public static Radians(degrees: number): number {
		return degrees * (3.14159265358979 / 180.0); // myDegree *=  3.141592 / 180 // degrees to radians
	}

	public static Degrees(radians: number): number {
		return radians * (180.0 / 3.14159265358979); // myRadian *= 180 / 3.141592 //  radian to degrees
	}
	public VectorOrigin: NVector3 = NVector3.Origin();
	public VectorSun: NVector3 = NVector3.Origin();
	public SunPoint: NVector3;

	public declination: number = 0;
	public solarAltitude: number = 0;
	public solarAzimuth: number = 0;
	public hourAngle: number = 0;

	public southDegree: number = 180; // 남쪽을 180도로 설정 (일반적인 관례)
	public sunDistance: number = 100;
	public SphereRadius: number = 10.0;

	public year: number = -1;
	public month: number = -1;
	public day: number = 1;
	public latitude: number = 42.3;
	public longitude: number = 0; // 경도 추가
	public hour: number = 14;
	public minute: number = 0; // 분 추가
	public timezone: number = 0; // 시간대 추가 (UTC 기준)

	constructor() {
		// 초기화
	}
	public update(latitude: number, longitude: number, year: number, month: number, day: number, hour: number, minute: number = 0, sundistance: number = 100, sphereSize: number = 10.0) {
		// 연중 일수 계산
		this.day = this.CalculateDayOfYear(year, month, day);
		this.month = month;
		this.year = year;
		this.latitude = latitude;
		this.longitude = longitude;
		this.hour = hour;
		this.minute = minute;

		// 경도로부터 시간대 자동 추출
		this.timezone = this.GetTimezoneFromCoordinates(latitude, longitude);

		this.sunDistance = sundistance;
		this.SphereRadius = sphereSize;

		// 태양 적위각 계산
		this.declination = this.CalculateDeclination(this.day);

		// 시간각 계산 (경도와 시간대 고려)
		this.hourAngle = this.CalculateHourAngle(this.hour, this.minute, this.longitude, this.timezone);

		// 태양 고도각 계산
		this.solarAltitude = this.CalculateSolarAltitude(this.latitude, this.declination, this.hourAngle);

		// 태양 방위각 계산
		this.solarAzimuth = this.CalculateSolarAzimuth(this.latitude, this.declination, this.hourAngle, this.solarAltitude);

		// 태양 벡터 계산 (정확한 3D 좌표계)
		this.CalculateSunVector();
	}

	/**
	 * 년월일로부터 연중 일수 계산
	 */
	private CalculateDayOfYear(year: number, month: number, day: number): number {
		const daysInMonth = [31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];

		// 윤년 확인
		if (this.IsLeapYear(year)) {
			daysInMonth[1] = 29;
		}

		let dayOfYear = 0;
		for (let i = 0; i < month - 1; i++) {
			dayOfYear += daysInMonth[i];
		}
		dayOfYear += day;

		return dayOfYear;
	}

	/**
	 * 윤년 확인
	 */
	private IsLeapYear(year: number): boolean {
		return (year % 4 === 0 && year % 100 !== 0) || year % 400 === 0;
	}

	/**
	 * GPS 좌표로부터 시간대 추출 (근사값)
	 */
	private GetTimezoneFromCoordinates(latitude: number, longitude: number): number {
		// 경도 기반 기본 시간대 계산 (15도당 1시간)
		let timezone = Math.round(longitude / 15);

		// 주요 국가/지역별 예외 처리
		if (this.IsInChina(latitude, longitude)) {
			return 8; // 중국 전체 UTC+8
		} else if (this.IsInIndia(latitude, longitude)) {
			return 5.5; // 인도 UTC+5:30
		} else if (this.IsInRussia(latitude, longitude)) {
			return this.GetRussianTimezone(longitude);
		} else if (this.IsInAustralia(latitude, longitude)) {
			return this.GetAustralianTimezone(latitude, longitude);
		} else if (this.IsInUSA(latitude, longitude)) {
			return this.GetUSATimezone(longitude);
		} else if (this.IsInCanada(latitude, longitude)) {
			return this.GetCanadaTimezone(longitude);
		} else if (this.IsInBrazil(latitude, longitude)) {
			return this.GetBrazilTimezone(longitude);
		} else if (this.IsInEurope(latitude, longitude)) {
			return this.GetEuropeanTimezone(longitude);
		}

		// 특별한 지역들
		if (longitude >= -180 && longitude < -157.5 && latitude >= 18.9 && latitude <= 28.4) {
			return -10; // 하와이
		}
		if (longitude >= -179 && longitude <= 179 && latitude >= -25 && latitude <= -8) {
			return 12; // 피지/뉴질랜드 부근
		}

		// 기본 경도 기반 계산
		return Math.max(-12, Math.min(14, timezone));
	}

	private IsInChina(lat: number, lng: number): boolean {
		return lat >= 18 && lat <= 54 && lng >= 73 && lng <= 135;
	}

	private IsInIndia(lat: number, lng: number): boolean {
		return lat >= 6 && lat <= 37 && lng >= 68 && lng <= 97;
	}

	private IsInRussia(lat: number, lng: number): boolean {
		return lat >= 41 && lat <= 82 && lng >= 19 && lng <= 180;
	}

	private GetRussianTimezone(lng: number): number {
		if (lng < 30) return 3; // 모스크바 시간
		if (lng < 45) return 4; // 사마라 시간
		if (lng < 60) return 5; // 예카테린부르크 시간
		if (lng < 75) return 6; // 옴스크 시간
		if (lng < 90) return 7; // 크라스노야르스크 시간
		if (lng < 105) return 8; // 이르쿠츠크 시간
		if (lng < 120) return 9; // 야쿠츠크 시간
		if (lng < 135) return 10; // 블라디보스토크 시간
		if (lng < 150) return 11; // 마가단 시간
		return 12; // 캄차카 시간
	}

	private IsInAustralia(lat: number, lng: number): boolean {
		return lat >= -44 && lat <= -10 && lng >= 112 && lng <= 154;
	}

	private GetAustralianTimezone(lat: number, lng: number): number {
		if (lng < 127.5) return 8; // 서호주 (AWST)
		if (lng < 137.5) return 9.5; // 중앙호주 (ACST)
		return 10; // 동호주 (AEST)
	}

	private IsInUSA(lat: number, lng: number): boolean {
		return lat >= 18.9 && lat <= 71.4 && lng >= -180 && lng <= -66;
	}

	private GetUSATimezone(lng: number): number {
		if (lng > -75) return -5; // 동부시간 (EST)
		if (lng > -90) return -6; // 중부시간 (CST)
		if (lng > -105) return -7; // 산악시간 (MST)
		if (lng > -125) return -8; // 태평양시간 (PST)
		if (lng > -140) return -9; // 알래스카 (AKST)
		return -10; // 하와이-알류샨 (HST)
	}

	private IsInCanada(lat: number, lng: number): boolean {
		return lat >= 41.7 && lat <= 83.1 && lng >= -141 && lng <= -52;
	}

	private GetCanadaTimezone(lng: number): number {
		if (lng > -60) return -4; // 대서양시간
		if (lng > -70) return -5; // 동부시간
		if (lng > -90) return -6; // 중부시간
		if (lng > -105) return -7; // 산악시간
		if (lng > -125) return -8; // 태평양시간
		if (lng > -135) return -9; // 유콘시간
		return -8; // 기본값
	}

	private IsInBrazil(lat: number, lng: number): boolean {
		return lat >= -34 && lat <= 5.3 && lng >= -74 && lng <= -32;
	}

	private GetBrazilTimezone(lng: number): number {
		if (lng > -38) return -3; // 브라질리아 시간
		if (lng > -52) return -3; // 브라질리아 시간
		if (lng > -68) return -4; // 아마존 시간
		return -5; // 아크레 시간
	}

	private IsInEurope(lat: number, lng: number): boolean {
		return lat >= 35 && lat <= 71 && lng >= -25 && lng <= 45;
	}

	private GetEuropeanTimezone(lng: number): number {
		if (lng < 7.5) return 0; // 서유럽시간 (GMT)
		if (lng < 22.5) return 1; // 중앙유럽시간 (CET)
		return 2; // 동유럽시간 (EET)
	}
	private CalculateDeclination(dayOfYear: number): number {
		// 더 정확한 적위각 공식
		const angle = (2 * Math.PI * (dayOfYear - 81)) / 365;
		return 23.45 * Math.sin(angle);
	}

	/**
	 * 시간각 계산 (경도와 시간대 고려)
	 */
	private CalculateHourAngle(hour: number, minute: number, longitude: number, timezone: number): number {
		// 지역 태양시 계산
		const localTime = hour + minute / 60;
		const solarTime = localTime + longitude / 15 - timezone;

		// 시간각 = (태양시 - 12) * 15도
		return (solarTime - 12) * 15;
	}

	/**
	 * 태양 고도각 계산
	 */
	private CalculateSolarAltitude(latitude: number, declination: number, hourAngle: number): number {
		const latRad = NSolarRobust.Radians(latitude);
		const decRad = NSolarRobust.Radians(declination);
		const hourRad = NSolarRobust.Radians(hourAngle);

		const sinAltitude = Math.sin(latRad) * Math.sin(decRad) + Math.cos(latRad) * Math.cos(decRad) * Math.cos(hourRad);

		return NSolarRobust.Degrees(Math.asin(Math.max(-1, Math.min(1, sinAltitude))));
	}

	/**
	 * 태양 방위각 계산 (남쪽 기준 0도, 시계방향)
	 */
	private CalculateSolarAzimuth(latitude: number, declination: number, hourAngle: number, altitude: number): number {
		const latRad = NSolarRobust.Radians(latitude);
		const decRad = NSolarRobust.Radians(declination);
		const hourRad = NSolarRobust.Radians(hourAngle);
		const altRad = NSolarRobust.Radians(altitude);

		const cosAzimuth = (Math.sin(decRad) - Math.sin(altRad) * Math.sin(latRad)) / (Math.cos(altRad) * Math.cos(latRad));

		let azimuth = NSolarRobust.Degrees(Math.acos(Math.max(-1, Math.min(1, cosAzimuth))));

		// 오후인 경우 방위각 조정
		if (hourAngle > 0) {
			azimuth = 360 - azimuth;
		}

		return azimuth;
	}

	/**
	 * 태양 벡터 계산 (3D 좌표계)
	 */
	private CalculateSunVector(): void {
		const altRad = NSolarRobust.Radians(this.solarAltitude);
		const azRad = NSolarRobust.Radians(this.solarAzimuth);

		// 구면 좌표를 직교 좌표로 변환
		// x: 동쪽 방향 (positive = 동쪽)
		// y: 북쪽 방향 (positive = 북쪽)
		// z: 위쪽 방향 (positive = 위쪽)
		this.VectorSun.x = Math.cos(altRad) * Math.sin(azRad);
		this.VectorSun.y = Math.cos(altRad) * Math.cos(azRad);
		this.VectorSun.z = Math.sin(altRad);

		// 벡터 정규화
		this.VectorSun.Unitize();

		// 태양 위치점 계산
		this.SunPoint = this.VectorSun.Mult(this.sunDistance);
	}

	/**
	 * 태양이 지평선 위에 있는지 확인
	 */
	public IsSunAboveHorizon(): boolean {
		return this.solarAltitude > 0;
	}

	/**
	 * 일출 시간 계산 (근사값)
	 */
	public CalculateSunrise(): number {
		const latRad = NSolarRobust.Radians(this.latitude);
		const decRad = NSolarRobust.Radians(this.declination);

		const cosHourAngle = -Math.tan(latRad) * Math.tan(decRad);

		if (Math.abs(cosHourAngle) > 1) {
			return NaN; // 극야 또는 백야
		}

		const hourAngle = NSolarRobust.Degrees(Math.acos(cosHourAngle));
		return 12 - hourAngle / 15;
	}

	/**
	 * 일몰 시간 계산 (근사값)
	 */
	public CalculateSunset(): number {
		const latRad = NSolarRobust.Radians(this.latitude);
		const decRad = NSolarRobust.Radians(this.declination);

		const cosHourAngle = -Math.tan(latRad) * Math.tan(decRad);

		if (Math.abs(cosHourAngle) > 1) {
			return NaN; // 극야 또는 백야
		}

		const hourAngle = NSolarRobust.Degrees(Math.acos(cosHourAngle));
		return 12 + hourAngle / 15;
	}

	/**
	 * 디버깅용 정보 출력
	 */
	public GetSolarInfo(): string {
		return `Solar Position Info:
        Day of Year: ${this.day}
        Latitude: ${this.latitude.toFixed(2)}°
        Longitude: ${this.longitude.toFixed(2)}°
        Time: ${this.hour}:${this.minute.toString().padStart(2, '0')}
        Timezone: UTC${this.timezone >= 0 ? '+' : ''}${this.timezone}
        
        Declination: ${this.declination.toFixed(2)}°
        Hour Angle: ${this.hourAngle.toFixed(2)}°
        Solar Altitude: ${this.solarAltitude.toFixed(2)}°
        Solar Azimuth: ${this.solarAzimuth.toFixed(2)}°
        
        Sun Vector: (${this.VectorSun.x.toFixed(3)}, ${this.VectorSun.y.toFixed(3)}, ${this.VectorSun.z.toFixed(3)})
        Above Horizon: ${this.IsSunAboveHorizon()}`;
	}
}

