// 1. 브라우저 환경에서 GPS 좌표로 현지 시간 가져오기

interface LocationTimeInfo {
	latitude: number;
	longitude: number;
	timezone: string;
	utcOffset: number;
	localTime: Date;
	year: number;
	month: number;
	day: number;
	hour: number;
	minute: number;
	second: number;
}

export class LocationTimeUtility {
	// 방법 1: TimeZone API 사용 (가장 정확함)
	static async getTimeFromCoordinatesAPI(lat: number, lng: number): Promise<LocationTimeInfo> {
		try {
			// TimeZone API 호출 (예: Google TimeZone API)
			const timestamp = Math.floor(Date.now() / 1000);
			const apiKey = 'YOUR_GOOGLE_API_KEY'; // 실제 API 키 필요

			const response = await fetch(`https://maps.googleapis.com/maps/api/timezone/json?location=${lat},${lng}&timestamp=${timestamp}&key=${apiKey}`);

			const data = await response.json();

			if (data.status === 'OK') {
				const utcOffset = (data.rawOffset + data.dstOffset) / 3600; // 시간 단위로 변환
				const localTime = new Date(Date.now() + utcOffset * 3600 * 1000);

				return {
					latitude: lat,
					longitude: lng,
					timezone: data.timeZoneId,
					utcOffset: utcOffset,
					localTime: localTime,
					year: localTime.getFullYear(),
					month: localTime.getMonth() + 1,
					day: localTime.getDate(),
					hour: localTime.getHours(),
					minute: localTime.getMinutes(),
					second: localTime.getSeconds(),
				};
			}
		} catch (error) {
			console.error('API Error:', error);
		}

		// API 실패시 fallback
		return this.getTimeFromCoordinatesOffline(lat, lng);
	}

	// 방법 2: 오프라인으로 근사 계산 (API 키 불필요)
	static getTimeFromCoordinatesOffline(lat: number, lng: number): LocationTimeInfo {
		const utcOffset = this.estimateTimezoneOffset(lat, lng);
		const timezone = this.getTimezoneId(lat, lng);

		// UTC 시간에 오프셋 적용
		const now = new Date();
		const utcTime = now.getTime() + now.getTimezoneOffset() * 60000;
		const localTime = new Date(utcTime + utcOffset * 3600000);

		return {
			latitude: lat,
			longitude: lng,
			timezone: timezone,
			utcOffset: utcOffset,
			localTime: localTime,
			year: localTime.getFullYear(),
			month: localTime.getMonth() + 1,
			day: localTime.getDate(),
			hour: localTime.getHours(),
			minute: localTime.getMinutes(),
			second: localTime.getSeconds(),
		};
	}

	// 방법 3: Intl.DateTimeFormat 사용 (브라우저 내장)
	static getTimeFromCoordinatesIntl(lat: number, lng: number): LocationTimeInfo {
		const timezone = this.getTimezoneId(lat, lng);
		const now = new Date();

		// Intl.DateTimeFormat으로 해당 시간대의 시간 계산
		const formatter = new Intl.DateTimeFormat('en-US', {
			timeZone: timezone,
			year: 'numeric',
			month: '2-digit',
			day: '2-digit',
			hour: '2-digit',
			minute: '2-digit',
			second: '2-digit',
			hour12: false,
		});

		const parts = formatter.formatToParts(now);
		const year = parseInt(parts.find((p) => p.type === 'year')?.value || '0');
		const month = parseInt(parts.find((p) => p.type === 'month')?.value || '0');
		const day = parseInt(parts.find((p) => p.type === 'day')?.value || '0');
		const hour = parseInt(parts.find((p) => p.type === 'hour')?.value || '0');
		const minute = parseInt(parts.find((p) => p.type === 'minute')?.value || '0');
		const second = parseInt(parts.find((p) => p.type === 'second')?.value || '0');

		const localTime = new Date(year, month - 1, day, hour, minute, second);
		const utcOffset = this.estimateTimezoneOffset(lat, lng);

		return {
			latitude: lat,
			longitude: lng,
			timezone: timezone,
			utcOffset: utcOffset,
			localTime: localTime,
			year: year,
			month: month,
			day: day,
			hour: hour,
			minute: minute,
			second: second,
		};
	}

	private static getTimezoneId(lat: number, lng: number): string {
		const timezones = [
			// 아시아
			{ bounds: [33, 43, 124, 132], tz: 'Asia/Seoul' },
			{ bounds: [30, 46, 129, 146], tz: 'Asia/Tokyo' },
			{ bounds: [18, 54, 73, 135], tz: 'Asia/Shanghai' },
			{ bounds: [6, 37, 68, 97], tz: 'Asia/Kolkata' },
			{ bounds: [1, 7, 103, 105], tz: 'Asia/Singapore' },
			{ bounds: [13, 19, 100, 106], tz: 'Asia/Bangkok' },

			// 북미
			{ bounds: [25, 50, -125, -66], tz: 'America/New_York' },
			{ bounds: [25, 50, -105, -90], tz: 'America/Chicago' },
			{ bounds: [25, 50, -125, -105], tz: 'America/Denver' },
			{ bounds: [32, 49, -125, -117], tz: 'America/Los_Angeles' },
			{ bounds: [18, 23, -161, -154], tz: 'Pacific/Honolulu' },

			// 유럽
			{ bounds: [49, 61, -8, 2], tz: 'Europe/London' },
			{ bounds: [47, 55, 2, 15], tz: 'Europe/Paris' },
			{ bounds: [55, 70, 10, 32], tz: 'Europe/Stockholm' },
			{ bounds: [35, 47, 12, 30], tz: 'Europe/Rome' },

			// 오세아니아
			{ bounds: [-44, -10, 112, 154], tz: 'Australia/Sydney' },
			{ bounds: [-35, -25, 115, 129], tz: 'Australia/Perth' },
			{ bounds: [-47, -34, 166, 179], tz: 'Pacific/Auckland' },

			// 남미
			{ bounds: [-34, 5, -74, -32], tz: 'America/Sao_Paulo' },
			{ bounds: [-55, -21, -74, -53], tz: 'America/Argentina/Buenos_Aires' },
		];

		for (const zone of timezones) {
			const [minLat, maxLat, minLng, maxLng] = zone.bounds;
			if (lat >= minLat && lat <= maxLat && lng >= minLng && lng <= maxLng) {
				return zone.tz;
			}
		}

		// UTC offset
		const offset = Math.round(lng / 15);
		if (offset >= 0) {
			return `Etc/GMT-${offset}`;
		} else {
			return `Etc/GMT+${Math.abs(offset)}`;
		}
	}

	// 시간대 오프셋 추정 (시간)
	private static estimateTimezoneOffset(lat: number, lng: number): number {
		// 특별한 지역들 처리
		if (lat >= 18 && lat <= 54 && lng >= 73 && lng <= 135) return 8; // 중국
		if (lat >= 6 && lat <= 37 && lng >= 68 && lng <= 97) return 5.5; // 인도
		if (lat >= -44 && lat <= -10 && lng >= 112 && lng <= 154) {
			// 호주
			if (lng < 127.5) return 8;
			if (lng < 137.5) return 9.5;
			return 10;
		}

		// 기본 경도 기반 계산
		return Math.max(-12, Math.min(14, Math.round(lng / 15)));
	}
}

export const executingAutoSunDirectionTimer = (callback, debuggerMode = true) => {
	let timeoutId = null;
	let intervalId = null;

	const now = new Date();

	const debuggerTime = debuggerMode ? 1000 : 60 * 1000;
	const msUntilNextMinute = (60 - now.getSeconds()) * 1000 - now.getMilliseconds();

	timeoutId = setTimeout(() => {
		if (debuggerMode) console.log('timer executing');
		callback();

		intervalId = setInterval(() => {
			if (debuggerMode) console.log('timer executing');
			callback();
			// }, debuggerTime);
		}, 60 * 1000);
	}, msUntilNextMinute);

	const destroy = () => {
		if (timeoutId !== null) clearTimeout(timeoutId);
		if (intervalId !== null) clearInterval(intervalId);

		if (debuggerMode) console.log('removed the timer!');
	};

	return destroy;
};
